CREATE TABLE workspace_settings(owner_id TEXT PRIMARY KEY REFERENCES local_profile(owner_id), time_zone TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE sections(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL CHECK(length(trim(name))>0), rank INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE labels(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES local_profile(owner_id), name TEXT NOT NULL CHECK(length(trim(name))>0), version INTEGER NOT NULL DEFAULT 0, UNIQUE(owner_id,name));
CREATE TABLE task_labels(task_id TEXT NOT NULL REFERENCES tasks(id), label_id TEXT NOT NULL REFERENCES labels(id), PRIMARY KEY(task_id,label_id));
ALTER TABLE tasks ADD COLUMN plan_value TEXT CHECK(plan_value IS NULL OR json_valid(plan_value));
ALTER TABLE tasks ADD COLUMN deadline_value TEXT CHECK(deadline_value IS NULL OR json_valid(deadline_value));
ALTER TABLE tasks ADD COLUMN follow_up_value TEXT CHECK(follow_up_value IS NULL OR json_valid(follow_up_value));
ALTER TABLE tasks ADD COLUMN priority_level INTEGER NOT NULL DEFAULT 4 CHECK(priority_level BETWEEN 1 AND 4);
ALTER TABLE tasks ADD COLUMN waiting INTEGER NOT NULL DEFAULT 0 CHECK(waiting IN(0,1));
ALTER TABLE tasks ADD COLUMN waiting_for TEXT NOT NULL DEFAULT '';
ALTER TABLE tasks ADD COLUMN waiting_note TEXT NOT NULL DEFAULT '';
ALTER TABLE tasks ADD COLUMN section_id TEXT REFERENCES sections(id);
ALTER TABLE tasks ADD COLUMN completed_at TEXT;
ALTER TABLE projects ADD COLUMN canceled INTEGER NOT NULL DEFAULT 0;
ALTER TABLE projects ADD COLUMN archived_at TEXT;
CREATE TABLE day_notes(owner_id TEXT NOT NULL REFERENCES local_profile(owner_id), date TEXT NOT NULL, outcome TEXT NOT NULL, closing TEXT NOT NULL, focus_ids TEXT NOT NULL CHECK(json_valid(focus_ids)), version INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(owner_id,date));
CREATE TABLE migration_reports(version INTEGER PRIMARY KEY, report TEXT NOT NULL);
UPDATE tasks SET deadline_value=json_object('kind','instant','atUtc',deadline,'displayTimezone',COALESCE(deadline_time_zone,'UTC')) WHERE deadline IS NOT NULL;
UPDATE tasks SET plan_value=(SELECT json_object('kind','date','date',MAX(execution_date)) FROM daily_plan_items p WHERE p.task_id=tasks.id AND p.removed=0 AND p.is_summary=0 HAVING count(*)>0);
UPDATE tasks SET completed_at=(SELECT occurred_at FROM execution_records WHERE id=tasks.active_completion_id) WHERE status='completed';
UPDATE projects SET archived_at=created_at,status=CASE WHEN EXISTS(SELECT 1 FROM tasks WHERE project_id=projects.id AND status NOT IN('completed','cancelled') AND deleted_at IS NULL) THEN 'paused' ELSE 'completed' END WHERE status='archived';
UPDATE projects SET archived_at=NULL WHERE status='paused';
INSERT INTO migration_reports VALUES(11,'每日安排最新有效日期作为初始计划，原安排与重点历史全部保留；甘特窗口不转换。旧截止保留确定时刻。P4 为新增默认值，旧重要标记不变。旧归档含未完成工作者恢复为暂停，其他归档保留并用创建时间作为兼容归档标记。多级树与叶子进度保留，新入口同时显示顶层统计。');
CREATE TRIGGER waiting_next AFTER UPDATE OF waiting ON tasks WHEN NEW.waiting=1 BEGIN UPDATE project_context SET next_action_task_id=NULL,next_action_cleared=1,version=version+1 WHERE next_action_task_id=NEW.id; END;
CREATE TRIGGER next_waiting_guard BEFORE UPDATE OF next_action_task_id ON project_context WHEN EXISTS(SELECT 1 FROM tasks WHERE id=NEW.next_action_task_id AND waiting=1) BEGIN SELECT RAISE(ABORT,'Waiting task cannot be next action'); END;
CREATE TRIGGER next_waiting_insert BEFORE INSERT ON project_context WHEN EXISTS(SELECT 1 FROM tasks WHERE id=NEW.next_action_task_id AND waiting=1) BEGIN SELECT RAISE(ABORT,'Waiting task cannot be next action'); END;
CREATE TRIGGER terminal_clear_waiting AFTER UPDATE OF status ON tasks WHEN NEW.status IN('completed','cancelled') AND NEW.deleted_at IS NULL BEGIN UPDATE tasks SET waiting=0,completed_at=CASE WHEN NEW.status='completed' THEN COALESCE(NEW.completed_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) ELSE NULL END WHERE id=NEW.id; END;
CREATE TRIGGER reopen_clear_time AFTER UPDATE OF status ON tasks WHEN NEW.status NOT IN('completed','cancelled') AND OLD.status IN('completed','cancelled') BEGIN UPDATE tasks SET completed_at=NULL WHERE id=NEW.id; END;
CREATE TRIGGER legacy_deadline AFTER UPDATE OF deadline ON tasks WHEN NEW.deadline IS NOT OLD.deadline BEGIN UPDATE tasks SET deadline_value=CASE WHEN NEW.deadline IS NULL THEN NULL ELSE json_object('kind','instant','atUtc',NEW.deadline,'displayTimezone',COALESCE(NEW.deadline_time_zone,'UTC')) END WHERE id=NEW.id; END;
CREATE TRIGGER terminal_children BEFORE UPDATE OF status ON tasks WHEN NEW.status IN('completed','cancelled') AND EXISTS(SELECT 1 FROM tasks WHERE parent_task_id=NEW.id AND deleted_at IS NULL AND status NOT IN('completed','cancelled')) BEGIN SELECT RAISE(ABORT,'请先明确处理未结束子任务'); END;
CREATE TRIGGER reopen_parent BEFORE UPDATE OF status ON tasks WHEN NEW.status NOT IN('completed','cancelled') AND EXISTS(SELECT 1 FROM tasks WHERE id=NEW.parent_task_id AND status IN('completed','cancelled')) BEGIN SELECT RAISE(ABORT,'请先重开父任务'); END;
CREATE TRIGGER terminal_project BEFORE UPDATE OF status ON projects WHEN NEW.status IN('completed','archived') AND EXISTS(SELECT 1 FROM tasks WHERE project_id=NEW.id AND deleted_at IS NULL AND status NOT IN('completed','cancelled')) BEGIN SELECT RAISE(ABORT,'请先处理项目未结束任务'); END;
CREATE TRIGGER reopen_project BEFORE UPDATE OF status ON tasks WHEN NEW.status NOT IN('completed','cancelled') AND EXISTS(SELECT 1 FROM projects WHERE id=NEW.project_id AND (status IN('completed','archived') OR canceled=1 OR archived_at IS NOT NULL)) BEGIN SELECT RAISE(ABORT,'请先重开项目'); END;
CREATE TRIGGER new_terminal_project BEFORE INSERT ON tasks WHEN EXISTS(SELECT 1 FROM projects WHERE id=NEW.project_id AND (status IN('completed','archived') OR canceled=1 OR archived_at IS NOT NULL)) BEGIN SELECT RAISE(ABORT,'请先重开项目'); END;
CREATE TRIGGER project_clear_next AFTER UPDATE OF status,canceled ON projects WHEN NEW.status<>'active' OR NEW.canceled=1 BEGIN UPDATE project_context SET next_action_task_id=NULL,next_action_cleared=1,version=version+1 WHERE project_id=NEW.id AND next_action_task_id IS NOT NULL; END;
DROP TRIGGER parent_insert;
DROP TRIGGER parent_update;
CREATE TRIGGER parent_insert BEFORE INSERT ON tasks WHEN NEW.parent_task_id IS NOT NULL BEGIN
 SELECT CASE WHEN NEW.id=NEW.parent_task_id OR NOT EXISTS(SELECT 1 FROM tasks p WHERE p.id=NEW.parent_task_id AND p.owner_id=NEW.owner_id AND p.project_id IS NEW.project_id AND p.deleted_at IS NULL AND p.status NOT IN('completed','cancelled')) THEN RAISE(ABORT,'Invalid parent reference') END;
END;
CREATE TRIGGER parent_update BEFORE UPDATE OF parent_task_id,owner_id,project_id ON tasks BEGIN
 SELECT CASE WHEN NEW.parent_task_id IS NOT NULL AND (NEW.id=NEW.parent_task_id OR NOT EXISTS(SELECT 1 FROM tasks p WHERE p.id=NEW.parent_task_id AND p.owner_id=NEW.owner_id AND p.project_id IS NEW.project_id AND p.deleted_at IS NULL)) THEN RAISE(ABORT,'Invalid parent reference') END;
 SELECT CASE WHEN EXISTS(WITH RECURSIVE ancestors(id,parent_id) AS(SELECT id,parent_task_id FROM tasks WHERE id=NEW.parent_task_id UNION SELECT t.id,t.parent_task_id FROM tasks t JOIN ancestors a ON t.id=a.parent_id) SELECT 1 FROM ancestors WHERE id=NEW.id) THEN RAISE(ABORT,'Parent cycle') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM tasks c WHERE c.parent_task_id=OLD.id AND (c.owner_id<>NEW.owner_id OR c.project_id IS NOT NEW.project_id)) THEN RAISE(ABORT,'Child project mismatch') END;
END;
CREATE TRIGGER inherit_section_insert AFTER INSERT ON tasks WHEN NEW.parent_task_id IS NOT NULL BEGIN UPDATE tasks SET section_id=(SELECT section_id FROM tasks WHERE id=NEW.parent_task_id) WHERE id=NEW.id; END;
CREATE TRIGGER inherit_section_move AFTER UPDATE OF parent_task_id ON tasks WHEN NEW.parent_task_id IS NOT NULL BEGIN UPDATE tasks SET section_id=(SELECT section_id FROM tasks WHERE id=NEW.parent_task_id) WHERE id=NEW.id; END;
CREATE TRIGGER propagate_section AFTER UPDATE OF section_id ON tasks WHEN NEW.section_id IS NOT OLD.section_id BEGIN UPDATE tasks SET section_id=NEW.section_id WHERE id IN(WITH RECURSIVE children(id) AS(SELECT id FROM tasks WHERE parent_task_id=NEW.id UNION ALL SELECT t.id FROM tasks t JOIN children c ON t.parent_task_id=c.id) SELECT id FROM children) AND section_id IS NOT NEW.section_id; END;
CREATE TRIGGER compatibility_schedule_insert AFTER INSERT ON daily_plan_items WHEN NEW.removed=0 AND NEW.is_summary=0 BEGIN UPDATE tasks SET plan_value=json_object('kind','date','date',NEW.execution_date) WHERE id=NEW.task_id; END;
CREATE TRIGGER compatibility_schedule_update AFTER UPDATE OF execution_date,removed,is_summary ON daily_plan_items WHEN NEW.removed=0 AND NEW.is_summary=0 BEGIN UPDATE tasks SET plan_value=json_object('kind','date','date',NEW.execution_date) WHERE id=NEW.task_id; END;
CREATE TRIGGER compatibility_clear_waiting AFTER UPDATE OF status ON tasks WHEN NEW.status<>OLD.status AND NEW.waiting=1 AND NEW.deleted_at IS NULL BEGIN UPDATE tasks SET waiting=0 WHERE id=NEW.id; END;
CREATE TRIGGER compatibility_reopen_project AFTER UPDATE OF status ON projects WHEN NEW.status IN('active','paused','draft') AND OLD.status IN('completed','archived') BEGIN UPDATE projects SET canceled=0,archived_at=NULL WHERE id=NEW.id; END;
CREATE TRIGGER compatibility_archive_project AFTER UPDATE OF status ON projects WHEN NEW.status='archived' BEGIN UPDATE projects SET archived_at=COALESCE(archived_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')),status='completed' WHERE id=NEW.id; END;
CREATE TRIGGER move_terminal_project BEFORE UPDATE OF project_id ON tasks WHEN NEW.project_id IS NOT OLD.project_id AND NEW.status NOT IN('completed','cancelled') AND EXISTS(SELECT 1 FROM projects WHERE id=NEW.project_id AND (status IN('completed','archived') OR canceled=1 OR archived_at IS NOT NULL)) BEGIN SELECT RAISE(ABORT,'请先重开目标项目'); END;
CREATE TRIGGER move_terminal_parent BEFORE UPDATE OF parent_task_id ON tasks WHEN NEW.parent_task_id IS NOT OLD.parent_task_id AND NEW.status NOT IN('completed','cancelled') AND EXISTS(SELECT 1 FROM tasks WHERE id=NEW.parent_task_id AND status IN('completed','cancelled')) BEGIN SELECT RAISE(ABORT,'请先重开父任务'); END;
CREATE TRIGGER archive_resolved_only BEFORE UPDATE OF status ON projects WHEN NEW.status='archived' AND OLD.status NOT IN('completed','archived') BEGIN SELECT RAISE(ABORT,'请先完成或取消项目'); END;

